    let percent24 = dataCOIN ? parseFloat(dataCOIN.percent_change_24h) : null;
    let percent7 = dataCOIN ? parseFloat(dataCOIN.percent_change_7d) : null;
    //Obtenemos el precio den bitcoin
    let precio_btc = dataCOIN ? parseFloat(dataCOIN.price_btc) : null;

    msg.payload = [{
        "precio": precio,
        "rank":rank,
        "percent_change_24h": percent24,
        "percent_change_7d": percent7,
        "price_btc": precio_btc
    },
    {
        tag1: nombre
    }];

} else {
    msg.payload = null; // si no encuentra la moneda
}

return msg;

